            ])
          : null,
      ]),
      card,
      tag ? h("p", { class: "slot__tag" }, tag) : null,
      revealed
        ? h("dl", { class: "kbju" }, [
            h("div", {}, [h("dt", {}, "Белки"), h("dd", {}, num(k.protein) + " г")]),
            h("div", {}, [h("dt", {}, "Жиры"), h("dd", {}, num(k.fat) + " г")]),
            h("div", {}, [h("dt", {}, "Углеводы"), h("dd", {}, num(k.carbs) + " г")]),
            h("div", {}, [h("dt", {}, "Энергия"), h("dd", {}, num(k.kcal) + " ккал")]),
