  border-color: var(--steel);
  background: transparent;
}

.slot--removed .card__photo,
.slot--removed .placard {
  opacity: 0.35;
  filter: grayscale(1);
}

.slot__tag {
  font-size: var(--t-sm);
  font-weight: 600;
}

.slot--winner .slot__tag {
  color: var(--mog);
}

.slot--wrong .slot__tag {
  color: var(--miss);
}

.kbju {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.4rem 0.75rem;
  padding: 0.7rem 0.8rem;
  background: var(--paper);
  font-size: var(--t-sm);
}

.kbju dt {
  color: #4d5869;
}

.kbju dd {
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}

/* Панель под лайнапом: мьюинг до выбора, вердикт и «Дальше» после. */
.controls {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.75rem 1.25rem;
  margin-top: 1.75rem;
  padding-top: 1.25rem;
  border-top: 3px solid var(--ink);
}

.controls__note {
  flex: 1 1 16rem;
  max-width: 34rem;
  font-size: var(--t-sm);
}

.controls--after {
  justify-content: space-between;
}

.verdict {
  flex: 1 1 18rem;
  font-weight: 600;
  font-size: var(--t-md);
  line-height: 1.35;
}

.verdict--hit {
  color: var(--mog);
}

.verdict--miss {
  color: var(--miss);
}

.btn--next {
  min-width: 9rem;
}

/* --- итог ------------------------------------------------------------------ */

.result {
  display: grid;
  grid-template-columns: minmax(0, 1.2fr) minmax(16rem, 1fr);
  grid-template-areas:
    "head ladder"
    "cart ladder";
  align-items: start;
  gap: 2rem clamp(1.5rem, 5vw, 4rem);
  max-width: 64rem;
  margin: 0 auto;
  padding: clamp(1.5rem, 5vw, 3rem) var(--gap) 4rem;
}

.result__head {
  grid-area: head;
  display: grid;
  justify-items: start;
  gap: 0.75rem;
}

.result__lead {
  font-weight: 500;
}

.result__rank {
  font: 900 var(--t-xxl) / 0.95 var(--display);
  letter-spacing: -0.02em;
  overflow-wrap: anywhere;
}

.result__stats {
  max-width: 30rem;
  font-size: var(--t-md);
  margin-bottom: 0.5rem;
}

.result__stats strong {
  font-family: var(--display);
}

/* Лестница рангов — тот же ростомер: true adam наверху, sub3 у пола. */
.ladder {
  grid-area: ladder;
  border-bottom: 3px solid var(--ink);
}

.rung {
  display: grid;
  grid-template-columns: 1fr auto;
  align-items: baseline;
  gap: 0 1rem;
  padding: 0.7rem 0.9rem;
  border-top: 1px solid var(--wall-deep);
}

.rung__name {
  font: 700 var(--t-md) / 1.2 var(--display);
}

.rung__range {
  font-size: var(--t-sm);
  font-variant-numeric: tabular-nums;
  color: #4d5869;
}

.rung--you {
  background: var(--ink);
  color: var(--paper);
  border-top-color: var(--ink);
}

.rung--you .rung__range {
  color: var(--wall);
}

.rung__you {
  grid-column: 1 / -1;
  font-size: var(--t-sm);
  font-weight: 600;
  color: #7fd9a8;
}

.cart {
  grid-area: cart;
  display: grid;
  gap: 0.9rem;
  padding: clamp(1rem, 3vw, 1.5rem);
  background: var(--paper);
  border: 3px solid var(--ink);
}

.cart h2 {
  font: 700 var(--t-lg) / 1.1 var(--display);
}

.cart__lead {
  font-size: var(--t-sm);
  color: #3d4859;
}

.picks {
  display: grid;
  border-top: 1px solid var(--wall-deep);
}

.pick {
  display: grid;
  grid-template-columns: 3.5rem 1fr auto;
  gap: 0.75rem;
  align-items: baseline;
  padding: 0.45rem 0;
  border-bottom: 1px solid var(--wall-deep);
  font-size: var(--t-sm);
}

.pick__mark {
  font-weight: 600;
}

.pick--hit .pick__mark {
  color: var(--mog);
}

.pick--miss .pick__mark {
  color: var(--miss);
}

.pick__price {
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

.cart__total {
  text-align: right;
}

.cart__total strong {
  font: 700 var(--t-md) / 1 var(--display);
}

.btn--cart {
  justify-self: start;
}

.cart__status {
  display: grid;
  gap: 0.3rem;
  padding: 0.8rem 0.9rem;
  border-left: 4px solid var(--ink);
  background: #fff;
}

.cart__status--done {
  border-left-color: var(--mog);
}

.cart__status--done a {
  font-weight: 600;
  color: var(--mog);
}

.cart__status--error {
  display: block;
  border-left-color: var(--miss);
}

.cart__link {
  font-size: var(--t-sm);
  color: #4d5869;
  overflow-wrap: anywhere;
}

/* --- адаптив --------------------------------------------------------------- */

@media (max-width: 760px) {
  :root {
    --chart: 9rem;
  }

  .bar {
    grid-template-columns: 1fr auto;
  }

  .bar__progress {
    grid-column: 1 / -1;
    grid-row: 2;
    width: 100%;
  }

  .result {
    grid-template-columns: minmax(0, 1fr);
    grid-template-areas:
      "head"
      "ladder"
      "cart";
  }
}

@media (max-width: 560px) {
  .lineup {
    padding-left: 2rem;
  }

  .lineup__scale {
    width: 1.8rem;
  }

  .slot__bar {
    left: 10%;
    right: 10%;
  }

  .slot__score {
    font-size: var(--t-sm);
  }

  .placard {
    padding: 0.5rem;
  }

  .placard__name {
    font-size: 0.72rem;
  }

  .placard__price {
    font-size: var(--t-sm);
  }

  .kbju {
    grid-template-columns: minmax(0, 1fr);
    padding: 0.5rem;
    font-size: 0.72rem;
    gap: 0.15rem;
  }

  .kbju div {
    display: flex;
    justify-content: space-between;
    gap: 0.25rem;
  }

  .slot__tag {
    font-size: 0.72rem;
  }

  .btn--next {
    width: 100%;
  }
}

@media (prefers-reduced-motion: reduce) {
  .slot__bar {
    animation: none;
  }
}

