// Временный драйвер скриншотов через Chrome DevTools Protocol (не часть проекта).
// node drive.js <cdpPort> <appUrl> <outDir>
const fs = require("node:fs");
const [port, appUrl, outDir] = process.argv.slice(2);

const SCENARIOS = {
  start: "",
  reveal: "cards()[0].click();",
  hint: "play(3); q('.btn--hint').click();",
  result: "play(10, 3); q('#cart-button').click();",
  adam: "play(10);",
  focus: "play(1); q('.btn--hint').focus();",
};

const HELPERS = `
  const q = (s) => document.querySelector(s);
  const cards = () => document.querySelectorAll('.card');
  const R = window.LOOKSMAX_ROUNDS;
  const win = (i) => R[i].products.findIndex((p) => p.id === R[i].winner_id);
  const play = (n, wrongEvery) => {
    for (let i = 0; i < n; i++) {
      const idx = wrongEvery && i % wrongEvery === 0 ? (win(i) + 1) % 3 : win(i);
      cards()[idx].click();
      q('#next').click();
    }
  };
`;

async function main() {
  const target = await (await fetch(`http://127.0.0.1:${port}/json/new?about:blank`, { method: "PUT" })).json();
  const ws = new WebSocket(target.webSocketDebuggerUrl);
  await new Promise((r) => ws.addEventListener("open", r, { once: true }));
  let id = 0;
  const pending = new Map();
  const events = [];
  ws.addEventListener("message", (m) => {
    const msg = JSON.parse(m.data);
    if (msg.id && pending.has(msg.id)) {
      pending.get(msg.id)(msg);
      pending.delete(msg.id);
    } else if (msg.method) {
      events.push(msg);
    }
  });
  const send = (method, params = {}) =>
    new Promise((r) => {
      const n = ++id;
      pending.set(n, r);
      ws.send(JSON.stringify({ id: n, method, params }));
    });
  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

  await send("Page.enable");
  await send("Runtime.enable");
  await send("Emulation.setEmulatedMedia", { features: [{ name: "prefers-reduced-motion", value: "reduce" }] });

  for (const width of [1280, 390]) {
    for (const [name, steps] of Object.entries(SCENARIOS)) {
      await send("Emulation.setDeviceMetricsOverride", { width, height: 900, deviceScaleFactor: 1, mobile: width < 500 });
      await send("Page.navigate", { url: appUrl });
      await sleep(1500);
      const res = await send("Runtime.evaluate", { expression: HELPERS + steps, awaitPromise: true });
      if (res.result.exceptionDetails) console.log(name, width, "ERROR", JSON.stringify(res.result.exceptionDetails).slice(0, 400));
      await sleep(1800);
      const shot = await send("Page.captureScreenshot", { format: "png", captureBeyondViewport: true });
      const file = `${outDir}/${name}-${width}.png`;
      fs.writeFileSync(file, Buffer.from(shot.result.data, "base64"));
      console.log(file);
    }
  }
  const errors = events.filter((e) => e.method === "Runtime.exceptionThrown");
  console.log("exceptions:", errors.length, errors.map((e) => e.params.exceptionDetails.text).join(" | "));
  ws.close();
}

main().catch((e) => {
  console.error(e);
  process.exit(1);
});

