.btn:hover:not(:disabled) {
  background: #2a3a5c;
}

.btn:disabled {
  cursor: not-allowed;
  background: transparent;
  color: #4d5869;
  border-color: var(--steel);
  border-style: dashed;
}

.btn--ghost {
  background: transparent;
  color: var(--ink);
}

.btn--ghost:hover:not(:disabled) {
  background: var(--paper);
}

.btn--cart {
  background: var(--mog);
  border-color: var(--mog);
}

.btn--cart:hover:not(:disabled) {
  background: #146a3e;
}

/* --- раунд ----------------------------------------------------------------- */

.round {
  max-width: 64rem;
  margin: 0 auto;
  padding: clamp(1.25rem, 4vw, 2.5rem) var(--gap) 3rem;
}

.round__head {
  max-width: 40rem;
  margin-bottom: 1.5rem;
}

.round__title {
  font: 900 var(--t-xl) / 1 var(--display);
  letter-spacing: -0.01em;
  margin-bottom: 0.6rem;
}

.round__ask {
  max-width: 34rem;
}

.round__formula {
  color: #3d4859;
}

/* Стена: горизонтальные деления каждые 0,1 скора, подписи каждые 0,2. */
.lineup {
  position: relative;
