    to bottom,
    var(--wall-deep) 0 1px,
    transparent 1px calc(var(--chart) / 10)
  );
  background-size: 100% var(--chart);
  background-position: 0 2rem;
  background-repeat: no-repeat;
}

.lineup__scale {
  position: absolute;
  top: 2rem;
  left: 0;
  height: var(--chart);
  width: 2.5rem;
}

.lineup__scale li {
  position: absolute;
  top: calc((1 - var(--v)) * 100%);
  transform: translateY(-50%);
  font: 500 var(--t-sm) / 1 var(--display);
  font-variant-numeric: tabular-nums;
  color: #4d5869;
}

.lineup__slots {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: var(--gap);
  align-items: start;
}

.slot {
  display: grid;
  gap: 0.6rem;
}

