  animation-delay: calc(var(--i) * 0.12s);
}

.slot--winner .slot__bar {
  background: var(--mog);
}

@keyframes rise {
  from {
    height: 0;
  }
}

.slot__score {
  position: absolute;
  bottom: 100%;
  left: 50%;
  transform: translateX(-50%);
  padding-bottom: 0.25rem;
  font: 700 var(--t-md) / 1 var(--display);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

.slot--winner .slot__score {
  color: var(--mog);
}

