.card {
  display: grid;
  width: 100%;
  padding: 0;
  border: 3px solid var(--ink);
  border-radius: 0;
  background: var(--ink);
  text-align: left;
  cursor: pointer;
}

.card:hover:not(:disabled) .placard {
  background: var(--mog);
}

.card:disabled {
  cursor: default;
}

.card__photo {
  display: block;
  aspect-ratio: 1;
  background: var(--paper);
}

.card__photo img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: contain;
  padding: 8%;
}

.placard {
  display: grid;
  gap: 0.35rem;
  padding: 0.7rem 0.8rem 0.8rem;
  background: var(--ink);
  color: var(--paper);
}

.placard__name {
  font-weight: 500;
