  padding-top: 1.25rem;
  border-top: 3px solid var(--ink);
}

.controls__note {
  flex: 1 1 16rem;
  max-width: 34rem;
  font-size: var(--t-sm);
}

.controls--after {
  justify-content: space-between;
}

.verdict {
