  color: #3d4859;
}

/* Стена: горизонтальные деления каждые 0,1 скора, подписи каждые 0,2. */
.lineup {
  position: relative;
  padding: 2rem 0 0 2.75rem;
  background-image: repeating-linear-gradient(
    to bottom,
    var(--wall-deep) 0 1px,
    transparent 1px calc(var(--chart) / 10)
  );
  background-size: 100% var(--chart);
  background-position: 0 2rem;
  background-repeat: no-repeat;
}

.lineup__scale {
  position: absolute;
  top: 2rem;
  left: 0;
  height: var(--chart);
  width: 2.5rem;
}

.lineup__scale li {
  position: absolute;
  top: calc((1 - var(--v)) * 100%);
  transform: translateY(-50%);
  font: 500 var(--t-sm) / 1 var(--display);
  font-variant-numeric: tabular-nums;
  color: #4d5869;
}

.lineup__slots {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: var(--gap);
  align-items: start;
}

.slot {
  display: grid;
  gap: 0.6rem;
}

/* Ростомер слота: пол — жирная линия чернил. */
.slot__height {
  position: relative;
  height: var(--chart);
  border-bottom: 3px solid var(--ink);
  margin-bottom: -0.6rem;
}

.slot__bar {
  position: absolute;
  left: 18%;
  right: 18%;
  bottom: 0;
  height: calc(var(--h) * 100%);
  background: var(--steel);
  animation: rise 0.8s cubic-bezier(0.2, 0.8, 0.2, 1) both;
