/* Looksmax Grocery: лайнап у ростомера. Скор товара — его рост на стене. */

:root {
  --wall: #c9d1d8;      /* стена лайнапа */
  --wall-deep: #b4bec8; /* линии ростомера, пустые деления */
  --ink: #18233a;       /* чернила: текст, таблички, пол */
  --paper: #f3f5f7;     /* фото и панели */
  --mog: #1a7f4b;       /* верно, победитель: заливки */
  --miss: #b83232;      /* неверно: заливки */
  --mog-text: #0f5c35;  /* те же цвета для текста на стене, контраст ≥ 4.5 */
  --miss-text: #8f1f1f;
  --brass: #c9971f;     /* лукс-коин */
  --steel: #7e8a99;     /* рост проигравших */

  --display: "Unbounded", "Arial Black", system-ui, sans-serif;
  --body: "Golos Text", system-ui, -apple-system, "Segoe UI", sans-serif;

  /* Шкала 1.25 */
  --t-sm: 0.8rem;
  --t-base: 1rem;
  --t-md: 1.25rem;
  --t-lg: 1.563rem;
  --t-xl: 2.441rem;
  --t-xxl: clamp(2.6rem, 9vw, 5.6rem);

  --chart: 15rem; /* высота ростомера = скор 1,0 */
  --gap: clamp(0.75rem, 2.5vw, 1.75rem);
  --focus: 0 0 0 3px var(--paper), 0 0 0 6px var(--ink);
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  -webkit-text-size-adjust: 100%;
}

body {
  margin: 0;
  min-height: 100vh;
  background: var(--wall);
  color: var(--ink);
  font: 400 var(--t-base) / 1.5 var(--body);
}

h1,
h2,
p,
ol,
ul,
dl,
dd {
  margin: 0;
}

ol,
ul {
  padding: 0;
  list-style: none;
}

button {
  font: inherit;
  color: inherit;
}

a {
  color: inherit;
}

:focus-visible {
  outline: none;
  box-shadow: var(--focus);
}

main:focus,
h1:focus {
  outline: none;
}

h1:focus-visible {
  box-shadow: none;
  text-decoration: underline 3px;
  text-underline-offset: 0.15em;
}

[hidden] {
  display: none !important;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
}

.note {
  padding: 2rem var(--gap);
}

/* --- шапка ----------------------------------------------------------------- */

.bar {
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: center;
  gap: var(--gap);
  padding: 0.9rem var(--gap);
  background: var(--ink);
  color: var(--paper);
}

.logo {
  font: 900 var(--t-sm) / 1.05 var(--display);
  letter-spacing: 0.01em;
  text-decoration: none;
}

.bar__progress {
  justify-self: center;
  display: grid;
  gap: 0.35rem;
  width: min(100%, 22rem);
}

.bar__round {
  font-size: var(--t-sm);
  font-weight: 500;
  text-align: center;
}

.ticks {
  display: grid;
  grid-template-columns: repeat(10, 1fr);
  gap: 4px;
}

.tick {
  height: 6px;
  background: #3a4660;
}

.tick--hit {
  background: #4cc58a;
}

.tick--miss {
  background: #e86a6a;
}

.tick--now {
  outline: 2px solid var(--paper);
  outline-offset: 2px;
}

.coins {
  display: flex;
  align-items: center;
  gap: 0.45rem;
  white-space: nowrap;
}

.coin {
  width: 1.1rem;
  height: 1.1rem;
  border-radius: 50%;
  background: var(--brass);
  box-shadow: inset 0 0 0 3px #e5bd55;
}

.coins__value {
  font: 700 var(--t-md) / 1 var(--display);
  font-variant-numeric: tabular-nums;
}

.coins__word {
  font-size: var(--t-sm);
}

/* --- кнопки ---------------------------------------------------------------- */

.btn {
  min-height: 3rem;
  padding: 0.7rem 1.4rem;
  border: 2px solid var(--ink);
  border-radius: 0.4rem;
  background: var(--ink);
  color: var(--paper);
  font-weight: 600;
  cursor: pointer;
}

.btn:hover:not(:disabled) {
  background: #2a3a5c;
}

.btn:disabled {
  cursor: not-allowed;
  background: transparent;
  color: #4d5869;
  border-color: var(--steel);
  border-style: dashed;
}

.btn--ghost {
  background: transparent;
  color: var(--ink);
}

.btn--ghost:hover:not(:disabled) {
  background: var(--paper);
}

.btn--cart {
  background: var(--mog);
  border-color: var(--mog);
}

.btn--cart:hover:not(:disabled) {
  background: #146a3e;
}

/* --- раунд ----------------------------------------------------------------- */

.round {
  max-width: 64rem;
  margin: 0 auto;
  padding: clamp(1.25rem, 4vw, 2.5rem) var(--gap) 3rem;
}

.round__head {
  max-width: 40rem;
  margin-bottom: 1.5rem;
}

.round__title {
  font: 900 var(--t-xl) / 1 var(--display);
  letter-spacing: -0.01em;
  margin-bottom: 0.6rem;
}

.round__ask {
  max-width: 34rem;
}

.round__formula {
  color: #3d4859;
}

/* Стена: горизонтальные деления каждые 0,1 скора, подписи каждые 0,2. */
.lineup {
  position: relative;
  padding: 2rem 0 0 2.75rem;
  background-image: repeating-linear-gradient(
    to bottom,
    var(--wall-deep) 0 1px,
    transparent 1px calc(var(--chart) / 10)
  );
  background-size: 100% var(--chart);
  background-position: 0 2rem;
  background-repeat: no-repeat;
}

.lineup__scale {
  position: absolute;
  top: 2rem;
  left: 0;
  height: var(--chart);
  width: 2.5rem;
}

.lineup__scale li {
  position: absolute;
  top: calc((1 - var(--v)) * 100%);
  transform: translateY(-50%);
  font: 500 var(--t-sm) / 1 var(--display);
  font-variant-numeric: tabular-nums;
  color: #4d5869;
}

.lineup__slots {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: var(--gap);
  align-items: start;
}

.slot {
  display: grid;
  gap: 0.6rem;
}

/* Ростомер слота: пол — жирная линия чернил. */
.slot__height {
  position: relative;
  height: var(--chart);
  border-bottom: 3px solid var(--ink);
  margin-bottom: -0.6rem;
}

.slot__bar {
  position: absolute;
  left: 18%;
  right: 18%;
  bottom: 0;
  height: calc(var(--h) * 100%);
  background: var(--steel);
  animation: rise 0.8s cubic-bezier(0.2, 0.8, 0.2, 1) both;
  animation-delay: calc(var(--i) * 0.12s);
}

.slot--winner .slot__bar {
  background: var(--mog);
}

@keyframes rise {
  from {
    height: 0;
  }
}

.slot__score {
  position: absolute;
  bottom: 100%;
  left: 50%;
  transform: translateX(-50%);
  padding-bottom: 0.25rem;
  font: 700 var(--t-md) / 1 var(--display);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

.slot--winner .slot__score {
  color: var(--mog);
}

/* Карточка: фото на бумаге + табличка как у задержанного. */
.card {
  display: grid;
  width: 100%;
  padding: 0;
  border: 3px solid var(--ink);
  border-radius: 0;
  background: var(--ink);
  text-align: left;
  cursor: pointer;
}

.card:hover:not(:disabled) .placard {
  background: var(--mog);
}

.card:disabled {
  cursor: default;
}

.card__photo {
  display: block;
  aspect-ratio: 1;
  background: var(--paper);
}

.card__photo img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: contain;
  padding: 8%;
}

.placard {
  display: grid;
  gap: 0.35rem;
  padding: 0.7rem 0.8rem 0.8rem;
  background: var(--ink);
  color: var(--paper);
}

.placard__name {
  font-weight: 500;
  line-height: 1.3;
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
  min-height: calc(1.3em * 3);
}

.placard__price {
  font: 700 var(--t-base) / 1 var(--display);
}

.slot--winner .card {
  border-color: var(--mog);
}

.slot--winner .placard {
  background: var(--mog);
}

.slot--wrong .card {
  border-color: var(--miss);
}

.slot--wrong .placard {
  background: var(--miss);
}

.slot--removed .card {
  border-style: dashed;
  border-color: var(--steel);
  background: transparent;
}

.slot--removed .card__photo,
.slot--removed .placard {
  opacity: 0.35;
  filter: grayscale(1);
}

.slot__tag {
  font-size: var(--t-sm);
  font-weight: 600;
}

.slot--winner .slot__tag {
  color: var(--mog);
}

.slot--wrong .slot__tag {
  color: var(--miss);
}

.kbju {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.4rem 0.75rem;
  padding: 0.7rem 0.8rem;
  background: var(--paper);
  font-size: var(--t-sm);
}

.kbju dt {
  color: #4d5869;
}

.kbju dd {
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}

/* Панель под лайнапом: мьюинг до выбора, вердикт и «Дальше» после. */
.controls {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.75rem 1.25rem;
  margin-top: 1.75rem;
  padding-top: 1.25rem;
  border-top: 3px solid var(--ink);
}

.controls__note {
  flex: 1 1 16rem;
  max-width: 34rem;
  font-size: var(--t-sm);
}

.controls--after {
  justify-content: space-between;
}

.verdict {
  flex: 1 1 18rem;
  font-weight: 600;
  font-size: var(--t-md);
  line-height: 1.35;
}

.verdict--hit {
  color: var(--mog);
}

.verdict--miss {
  color: var(--miss);
}

.btn--next {
  min-width: 9rem;
}

/* --- итог ------------------------------------------------------------------ */

.result {
  display: grid;
  grid-template-columns: minmax(0, 1.2fr) minmax(16rem, 1fr);
  grid-template-areas:
    "head ladder"
    "cart ladder";
  align-items: start;
  gap: 2rem clamp(1.5rem, 5vw, 4rem);
  max-width: 64rem;
  margin: 0 auto;
  padding: clamp(1.5rem, 5vw, 3rem) var(--gap) 4rem;
}

.result__head {
  grid-area: head;
  display: grid;
  justify-items: start;
  gap: 0.75rem;
}

.result__lead {
  font-weight: 500;
}

.result__rank {
  font: 900 var(--t-xxl) / 0.95 var(--display);
  letter-spacing: -0.02em;
  overflow-wrap: anywhere;
}

.result__stats {
  max-width: 30rem;
  font-size: var(--t-md);
  margin-bottom: 0.5rem;
}

.result__stats strong {
  font-family: var(--display);
}

/* Лестница рангов — тот же ростомер: true adam наверху, sub3 у пола. */
.ladder {
  grid-area: ladder;
  border-bottom: 3px solid var(--ink);
}

.rung {
  display: grid;
  grid-template-columns: 1fr auto;
  align-items: baseline;
  gap: 0 1rem;
  padding: 0.7rem 0.9rem;
  border-top: 1px solid var(--wall-deep);
}

.rung__name {
  font: 700 var(--t-md) / 1.2 var(--display);
}

.rung__range {
  font-size: var(--t-sm);
  font-variant-numeric: tabular-nums;
  color: #4d5869;
}

.rung--you {
  background: var(--ink);
  color: var(--paper);
  border-top-color: var(--ink);
}

.rung--you .rung__range {
  color: var(--wall);
}

.rung__you {
  grid-column: 1 / -1;
  font-size: var(--t-sm);
  font-weight: 600;
  color: #7fd9a8;
}

.cart {
  grid-area: cart;
  display: grid;
  gap: 0.9rem;
  padding: clamp(1rem, 3vw, 1.5rem);
  background: var(--paper);
  border: 3px solid var(--ink);
}

.cart h2 {
  font: 700 var(--t-lg) / 1.1 var(--display);
}

.cart__lead {
  font-size: var(--t-sm);
  color: #3d4859;
}

.picks {
  display: grid;
  border-top: 1px solid var(--wall-deep);
}

.pick {
  display: grid;
  grid-template-columns: 3.5rem 1fr auto;
  gap: 0.75rem;
  align-items: baseline;
  padding: 0.45rem 0;
  border-bottom: 1px solid var(--wall-deep);
  font-size: var(--t-sm);
}

.pick__mark {
  font-weight: 600;
}

.pick--hit .pick__mark {
  color: var(--mog);
}

.pick--miss .pick__mark {
  color: var(--miss);
}

.pick__price {
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

.cart__total {
  text-align: right;
}

.cart__total strong {
  font: 700 var(--t-md) / 1 var(--display);
}

.btn--cart {
  justify-self: start;
}

.cart__status {
  display: grid;
  gap: 0.3rem;
  padding: 0.8rem 0.9rem;
  border-left: 4px solid var(--ink);
  background: #fff;
}

.cart__status--done {
  border-left-color: var(--mog);
}

.cart__status--done a {
  font-weight: 600;
  color: var(--mog);
}

.cart__status--error {
  display: block;
  border-left-color: var(--miss);
}

.cart__link {
  font-size: var(--t-sm);
  color: #4d5869;
  overflow-wrap: anywhere;
}

/* --- адаптив --------------------------------------------------------------- */

@media (max-width: 760px) {
  :root {
    --chart: 9rem;
  }

  .bar {
    grid-template-columns: 1fr auto;
  }

  .bar__progress {
    grid-column: 1 / -1;
    grid-row: 2;
    width: 100%;
  }

  .result {
    grid-template-columns: minmax(0, 1fr);
    grid-template-areas:
      "head"
      "ladder"
      "cart";
  }
}

@media (max-width: 560px) {
  .lineup {
    padding-left: 2rem;
  }

  .lineup__scale {
    width: 1.8rem;
  }

  .slot__bar {
    left: 10%;
    right: 10%;
  }

  .slot__score {
    font-size: var(--t-sm);
  }

  .placard {
    padding: 0.5rem;
  }

  .placard__name {
    font-size: 0.72rem;
  }

  .placard__price {
    font-size: var(--t-sm);
  }

  .kbju {
    grid-template-columns: minmax(0, 1fr);
    padding: 0.5rem;
    font-size: 0.72rem;
    gap: 0.15rem;
  }

  .kbju div {
    display: flex;
    justify-content: space-between;
    gap: 0.25rem;
  }

  .slot__tag {
    font-size: 0.72rem;
  }

  .btn--next {
    width: 100%;
  }
}

@media (prefers-reduced-motion: reduce) {
  .slot__bar {
    animation: none;
  }
}

input.new_string:
.slot--winner .slot__score {
  color: var(--mog-text);
}

tool_use_result.newString:
.slot--winner .slot__score {
  color: var(--mog-text);
}

