  color: var(--paper);
  border-top-color: var(--ink);
}

.rung--you .rung__range {
  color: var(--wall);
}

.rung__you {
  grid-column: 1 / -1;
  font-size: var(--t-sm);
  font-weight: 600;
  color: #7fd9a8;
}

.cart {
  grid-area: cart;
