  border: 3px solid var(--ink);
}

.cart h2 {
  font: 700 var(--t-lg) / 1.1 var(--display);
}

.cart__lead {
  font-size: var(--t-sm);
  color: #3d4859;
}

.picks {
  display: grid;
  border-top: 1px solid var(--wall-deep);
}

.pick {
  display: grid;
  grid-template-columns: 3.5rem 1fr auto;
  gap: 0.75rem;
  align-items: baseline;
  padding: 0.45rem 0;
  border-bottom: 1px solid var(--wall-deep);
  font-size: var(--t-sm);
}

.pick__mark {
  font-weight: 600;
}

.pick--hit .pick__mark {
  color: var(--mog);
}

.pick--miss .pick__mark {
  color: var(--miss);
}

.pick__price {
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

.cart__total {
  text-align: right;
}

.cart__total strong {
  font: 700 var(--t-md) / 1 var(--display);
}

.btn--cart {
  justify-self: start;
}

.cart__status {
  display: grid;
  gap: 0.3rem;
  padding: 0.8rem 0.9rem;
  border-left: 4px solid var(--ink);
  background: #fff;
}

.cart__status--done {
  border-left-color: var(--mog);
}

.cart__status--done a {
  font-weight: 600;
  color: var(--mog);
}

.cart__status--error {
  display: block;
  border-left-color: var(--miss);
}

.cart__link {
  font-size: var(--t-sm);
  color: #4d5869;
  overflow-wrap: anywhere;
}

/* --- адаптив --------------------------------------------------------------- */

@media (max-width: 760px) {
  :root {
    --chart: 9rem;
  }

  .bar {
    grid-template-columns: 1fr auto;
  }

  .bar__progress {
    grid-column: 1 / -1;
    grid-row: 2;
    width: 100%;
  }

  .result {
    grid-template-columns: minmax(0, 1fr);
    grid-template-areas:
      "head"
      "ladder"
      "cart";
  }
}

@media (max-width: 560px) {
  .lineup {
    padding-left: 2rem;
  }

  .lineup__scale {
    width: 1.8rem;
  }

  .slot__bar {
    left: 10%;
    right: 10%;
  }

  .slot__score {
    font-size: var(--t-sm);
  }

  .placard {
    padding: 0.5rem;
  }

  .placard__name {
    font-size: 0.72rem;
  }

  .placard__price {
    font-size: var(--t-sm);
  }

  .kbju {
    grid-template-columns: minmax(0, 1fr);
    padding: 0.5rem;
    font-size: 0.72rem;
    gap: 0.15rem;
  }

  .kbju div {
    display: flex;
    justify-content: space-between;
    gap: 0.25rem;
  }

  .slot__tag {
    font-size: 0.72rem;
  }

  .btn--next {
    width: 100%;
  }
}

@media (prefers-reduced-motion: reduce) {
  .slot__bar {
    animation: none;
  }
}

