  --wall: #c9d1d8;      /* стена лайнапа */
  --wall-deep: #b4bec8; /* линии ростомера, пустые деления */
  --ink: #18233a;       /* чернила: текст, таблички, пол */
  --paper: #f3f5f7;     /* фото и панели */
  --mog: #1a7f4b;       /* верно, победитель: заливки */
  --miss: #b83232;      /* неверно: заливки */
  --mog-text: #0f5c35;  /* те же цвета для текста на стене, контраст ≥ 4.5 */
  --miss-text: #8f1f1f;
  --brass: #c9971f;     /* лукс-коин */
  --steel: #7e8a99;     /* рост проигравших */

  --display: "Unbounded", "Arial Black", system-ui, sans-serif;
  --body: "Golos Text", system-ui, -apple-system, "Segoe UI", sans-serif;

  /* Шкала 1.25 */
  --t-sm: 0.8rem;
  --t-base: 1rem;
  --t-md: 1.25rem;
  --t-lg: 1.563rem;
  --t-xl: 2.441rem;
  --t-xxl: clamp(2.6rem, 9vw, 5.6rem);

  --chart: 15rem; /* высота ростомера = скор 1,0 */
  --gap: clamp(0.75rem, 2.5vw, 1.75rem);
  --focus: 0 0 0 3px var(--paper), 0 0 0 6px var(--ink);
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  -webkit-text-size-adjust: 100%;
}

body {
  margin: 0;
  min-height: 100vh;
  background: var(--wall);
  color: var(--ink);
  font: 400 var(--t-base) / 1.5 var(--body);
}

h1,
h2,
p,
ol,
ul,
dl,
dd {
  margin: 0;
}

ol,
ul {
  padding: 0;
  list-style: none;
}

button {
  font: inherit;
  color: inherit;
}

a {
  color: inherit;
}

:focus-visible {
  outline: none;
  box-shadow: var(--focus);
}

main:focus,
h1:focus {
  outline: none;
}

h1:focus-visible {
  box-shadow: none;
  text-decoration: underline 3px;
  text-underline-offset: 0.15em;
}

[hidden] {
  display: none !important;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
}

.note {
  padding: 2rem var(--gap);
}

/* --- шапка ----------------------------------------------------------------- */

.bar {
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: center;
  gap: var(--gap);
  padding: 0.9rem var(--gap);
  background: var(--ink);
  color: var(--paper);
}

.logo {
  font: 900 var(--t-sm) / 1.05 var(--display);
  letter-spacing: 0.01em;
  text-decoration: none;
}

.bar__progress {
  justify-self: center;
  display: grid;
  gap: 0.35rem;
  width: min(100%, 22rem);
}

.bar__round {
  font-size: var(--t-sm);
  font-weight: 500;
  text-align: center;
}

.ticks {
  display: grid;
  grid-template-columns: repeat(10, 1fr);
  gap: 4px;
}

.tick {
  height: 6px;
  background: #3a4660;
}

.tick--hit {
  background: #4cc58a;
}

.tick--miss {
  background: #e86a6a;
}

.tick--now {
  outline: 2px solid var(--paper);
  outline-offset: 2px;
}

.coins {
  display: flex;
  align-items: center;
  gap: 0.45rem;
  white-space: nowrap;
}

.coin {
  width: 1.1rem;
  height: 1.1rem;
  border-radius: 50%;
  background: var(--brass);
  box-shadow: inset 0 0 0 3px #e5bd55;
}

.coins__value {
  font: 700 var(--t-md) / 1 var(--display);
