/* Looksmax Grocery: лайнап у ростомера. Скор товара — его рост на стене. */

:root {
  --wall: #c9d1d8;      /* стена лайнапа */
  --wall-deep: #b4bec8; /* линии ростомера, пустые деления */
  --ink: #18233a;       /* чернила: текст, таблички, пол */
  --paper: #f3f5f7;     /* фото и панели */
  --mog: #1a7f4b;       /* верно, победитель: заливки */
  --miss: #b83232;      /* неверно: заливки */
  --mog-text: #0f5c35;  /* те же цвета для текста на стене, контраст ≥ 4.5 */
  --miss-text: #8f1f1f;
  --brass: #c9971f;     /* лукс-коин */
  --steel: #7e8a99;     /* рост проигравших */

  --display: "Unbounded", "Arial Black", system-ui, sans-serif;
  --body: "Golos Text", system-ui, -apple-system, "Segoe UI", sans-serif;

  /* Шкала 1.25 */
  --t-sm: 0.8rem;
  --t-base: 1rem;
  --t-md: 1.25rem;
  --t-lg: 1.563rem;
  --t-xl: 2.441rem;
  --t-xxl: clamp(2.6rem, 9vw, 5.6rem);

  --chart: 15rem; /* высота ростомера = скор 1,0 */
  --gap: clamp(0.75rem, 2.5vw, 1.75rem);
  --focus: 0 0 0 3px var(--paper), 0 0 0 6px var(--ink);
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  -webkit-text-size-adjust: 100%;
}

body {
  margin: 0;
  min-height: 100vh;
  background: var(--wall);
  color: var(--ink);
  font: 400 var(--t-base) / 1.5 var(--body);
}

h1,
h2,
p,
ol,
ul,
dl,
dd {
  margin: 0;
}

ol,
ul {
  padding: 0;
  list-style: none;
}

button {
  font: inherit;
  color: inherit;
}

a {
  color: inherit;
}

:focus-visible {
  outline: none;
  box-shadow: var(--focus);
}

main:focus,
h1:focus {
  outline: none;
}

h1:focus-visible {
  box-shadow: none;
  text-decoration: underline 3px;
  text-underline-offset: 0.15em;
}

[hidden] {
  display: none !important;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
}

.note {
  padding: 2rem var(--gap);
}

/* --- шапка ----------------------------------------------------------------- */

.bar {
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: center;
  gap: var(--gap);
  padding: 0.9rem var(--gap);
  background: var(--ink);
  color: var(--paper);
}

.logo {
  font: 900 var(--t-sm) / 1.05 var(--display);
  letter-spacing: 0.01em;
  text-decoration: none;
}

.bar__progress {
  justify-self: center;
  display: grid;
  gap: 0.35rem;
  width: min(100%, 22rem);
}

.bar__round {
  font-size: var(--t-sm);
  font-weight: 500;
  text-align: center;
}

.ticks {
  display: grid;
  grid-template-columns: repeat(10, 1fr);
  gap: 4px;
}

.tick {
  height: 6px;
  background: #3a4660;
}

.tick--hit {
  background: #4cc58a;
}

.tick--miss {
  background: #e86a6a;
}

.tick--now {
  outline: 2px solid var(--paper);
  outline-offset: 2px;
}

.coins {
  display: flex;
  align-items: center;
  gap: 0.45rem;
  white-space: nowrap;
}

.coin {
  width: 1.1rem;
  height: 1.1rem;
  border-radius: 50%;
  background: var(--brass);
  box-shadow: inset 0 0 0 3px #e5bd55;
}

.coins__value {
  font: 700 var(--t-md) / 1 var(--display);
  font-variant-numeric: tabular-nums;
}

.coins__word {
  font-size: var(--t-sm);
}

/* --- кнопки ---------------------------------------------------------------- */

.btn {
  min-height: 3rem;
  padding: 0.7rem 1.4rem;
  border: 2px solid var(--ink);
  border-radius: 0.4rem;
  background: var(--ink);
  color: var(--paper);
  font-weight: 600;
  cursor: pointer;
}

.btn:hover:not(:disabled) {
  background: #2a3a5c;
}

.btn:disabled {
  cursor: not-allowed;
  background: transparent;
  color: #4d5869;
  border-color: var(--steel);
  border-style: dashed;
}

.btn--ghost {
  background: transparent;
  color: var(--ink);
}

.btn--ghost:hover:not(:disabled) {
  background: var(--paper);
}

.btn--cart {
  justify-self: start;
  background: var(--mog);
  border-color: var(--mog);
}

.btn--cart:hover:not(:disabled) {
  background: #146a3e;
}

/* --- раунд ----------------------------------------------------------------- */

.round {
  max-width: 64rem;
  margin: 0 auto;
  padding: clamp(1.25rem, 4vw, 2.5rem) var(--gap) 3rem;
}

.round__head {
  max-width: 40rem;
  margin-bottom: 1.5rem;
}

.round__title {
  font: 900 var(--t-xl) / 1 var(--display);
  letter-spacing: -0.01em;
  margin-bottom: 0.6rem;
}

.round__ask {
  max-width: 34rem;
}

.round__formula {
  color: #3d4859;
}

/* Стена: горизонтальные деления каждые 0,1 скора, подписи каждые 0,2. */
.lineup {
  position: relative;
  padding: 2rem 0 0 2.75rem;
  background-image: repeating-linear-gradient(
    to bottom,
    var(--wall-deep) 0 1px,
    transparent 1px calc(var(--chart) / 10)
  );
  background-size: 100% var(--chart);
  background-position: 0 2rem;
  background-repeat: no-repeat;
}

.lineup__scale {
  position: absolute;
  top: 2rem;
  left: 0;
  height: var(--chart);
  width: 2.5rem;
}

.lineup__scale li {
  position: absolute;
  top: calc((1 - var(--v)) * 100%);
  transform: translateY(-50%);
  padding-right: 0.3rem;
  background: var(--wall);
  font: 500 var(--t-sm) / 1 var(--display);
  font-variant-numeric: tabular-nums;
  color: #4d5869;
}

.lineup__slots {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: var(--gap);
  align-items: start;
}

.slot {
  display: grid;
  gap: 0.6rem;
}

/* Ростомер слота: пол — жирная линия чернил. */
.slot__height {
  position: relative;
  height: var(--chart);
  border-bottom: 3px solid var(--ink);
  margin-bottom: -0.6rem;
}

.slot__bar {
  position: absolute;
  left: 18%;
  right: 18%;
  bottom: 0;
  height: calc(var(--h) * 100%);
  background: var(--steel);
  animation: rise 0.8s cubic-bezier(0.2, 0.8, 0.2, 1) both;
  animation-delay: calc(var(--i) * 0.12s);
}

.slot--winner .slot__bar {
  background: var(--mog);
}

@keyframes rise {
  from {
    height: 0;
  }
}

.slot__score {
  position: absolute;
  bottom: 100%;
  left: 50%;
  transform: translateX(-50%);
  padding-bottom: 0.25rem;
  font: 700 var(--t-md) / 1 var(--display);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

.slot--winner .slot__score {
  color: var(--mog-text);
}

